function overview(){return `<div class="page overview"><div class="page-title"><div><div class="project-kicker"><span class="small-square"></span> 私宅设计 / 官山有溪</div><h1>空间有据，风格有源。</h1><p>从他们的设计出发，让每一种表达都回到同一张平面。</p></div><button class="btn dark" data-route="workspace">进入空间工作台 ${ico('arrow')}</button></div><section class="proposal-hero"><div class="hero-art"><img src="${asset('original-living.jpg')}" alt="官山有溪原案客厅：弧形沙发、独立座椅、庭院与咖啡区"><span class="image-tag">客户原案 · 非 AI 试生成</span><div class="hero-type"><small>Guanshan Youxi</small><h2>以庭院为序，<br>收藏日常。</h2></div><button class="hero-expand icon-btn" data-file="original-living.jpg" data-caption="客户原案 · 官山有溪第43页" aria-label="放大原案客厅">${ico('expand')}</button><span class="hero-credit">原案来源 / 官山有溪 P.43</span></div><div class="plan-leaf"><div class="leaf-heading"><span>这一次，从真实方案开始</span><span class="leaf-number">01 / F</span></div><button class="leaf-plan" data-page="guanshan:40" aria-label="查看首层平面原页"><img src="${asset('guanshan-p40.jpg')}" alt="官山有溪首层设计平面"></button><div class="leaf-copy"><h3>一张平面，<br>两种设计语言。</h3><p>客厅、咖啡区、品茗区与庭院，<br>在同一空间依据下展开。</p></div><div class="leaf-stats"><div><strong>02</strong><small>风格方向</small></div><div><strong>04</strong><small>AI 试生成</small></div><div><strong>05</strong><small>客户资料</small></div></div><button class="leaf-link" data-route="review">对照平面，查看试验 ${ico('arrow')}</button></div></section><section class="intent-strip"><div><b>空间先于画面</b><p>墙体、开口、房间关系与家具落点，逐项回到图纸。</p></div><div><b>理解先于风格</b><p>把材质、造型与布光拆开说清，保留可追溯的参考。</p></div><div><b>结果接受核对</b><p>美观与准确分别评估，生成偏差形成下一轮修改依据。</p></div></section><div class="section-head"><div><h2>同一张平面，两种空间气质</h2><p>以下为本次实际试生成，尚未通过空间精度验收。</p></div><button class="text-btn" data-route="styles">阅读风格依据 ${ico('arrow')}</button></div><div class="direction-grid">${styles.map(s=>`<button class="direction-card" data-open-style="${s.id}"><div class="direction-image"><img src="${photo(s.id)}" alt="${s.name}客厅AI试生成" loading="lazy"><span class="image-tag">AI 试生成 · 待校核</span><span class="circle-arrow">${ico('arrow')}</span></div><div class="direction-caption"><div><small>${s.en}</small><h3>${s.name}</h3><p>${s.subtitle}</p></div><span class="swatches">${s.colors.map(c=>`<i style="background:${c}"></i>`).join('')}</span></div></button>`).join('')}</div><div class="source-banner"><div><small>来自客户的设计档案</small><h2>理解一种审美，先读懂它的作品。</h2><p>官山有溪 · Rimadesio · 谧享家 · 达普利 · 私宅设计建议书</p></div><button class="btn" data-route="archive">展开素材档案 ${ico('arrow')}</button></div></div>`;}
function planPanel(interactive=true){return `<div class="plan-map"><img src="${state.custom?uploads.plan||asset('guanshan-p40.jpg'):asset('guanshan-p40.jpg')}" alt="${state.custom?'导入平面':'官山有溪首层平面，第40页'}">${!state.custom&&interactive?rooms.map(r=>`<button class="map-pin ${state.room===r.id?'active':''}" style="left:${r.x}%;top:${r.y}%" data-room="${r.id}" aria-label="定位${r.name}">${r.n}</button>`).join(''):''}${!state.custom&&interactive?(()=>{const r=rooms.find(r=>r.id===state.room)||rooms[0];return `<div class="map-highlight" style="left:${r.rect[0]}%;top:${r.rect[1]}%;width:${r.rect[2]}%;height:${r.rect[3]}%"></div>`;})():''}</div>`;}
function viewImage(){if(state.view==='plan')return state.custom?uploads.plan:asset('guanshan-p40.jpg');if(state.view==='original')return asset('original-living.jpg');return photo(state.style,state.view);}
function workspace(){const s=byStyle(state.style),r=rooms.find(r=>r.id===state.room)||rooms[0],allowed=!state.custom||state.view==='plan';return `<div class="page workspace"><div class="work-heading"><div><div class="project-kicker">${state.custom?'客户素材准备':'官山有溪 / 首层验证'}</div><h1>${esc(title())}</h1><p>${state.custom?'新素材仅用于准备生成简报；内置试验不应用于此图纸。':'空间依据：第40页平面 · 客厅机位 C1 · 两种风格试验'}</p></div><div class="actions"><button class="btn" data-action="history">${ico('clock')} 历史方案</button><button class="btn" data-action="save">保存方案</button><button class="btn dark" data-action="export">${ico('download')} 导出</button></div></div><div class="workflow"><button data-view="plan" class="${state.view==='plan'?'active':''}"><span>01</span> 读取空间 <small>以确认平面为依据</small></button><button data-route="styles"><span>02</span> 定义风格 <small>从案例提炼设计语言</small></button><button data-route="review"><span>03</span> 生成与核对 <small>人视、轴侧分别评审</small></button></div><div class="studio-grid"><section class="canvas-panel"><div class="canvas-toolbar"><div class="segmented">${[['plan','设计平面'],['original','客户原案'],['perspective','人视试生成'],['axon','首层轴侧']].map(([v,n])=>`<button data-view="${v}" class="${state.view===v?'active':''}" aria-pressed="${state.view===v}">${n}</button>`).join('')}</div><button class="icon-btn" data-action="focus" aria-label="${focused?'退出专注':'专注预览'}">${ico('expand')}</button></div><div class="canvas-stage ${state.view==='plan'?'plan-stage':''}" id="stage">${allowed?(state.view==='plan'?planPanel(true):`<img class="result-img" src="${viewImage()}" alt="${state.view==='original'?'客户原案':s.name+(state.view==='axon'?'首层轴侧':'客厅人视')+'AI试生成'}"><span class="image-tag">${state.view==='original'?'客户原案 · 第43页':'AI 试生成 · 待校核'}</span>`):'<div class="empty-state">'+ico('work')+'<h3>先让这张平面拥有自己的结果</h3><p>当前是新导入的图纸，尚无对应生成图。<br>可整理风格要求与参考素材，导出生成简报。</p><button class="btn" data-view="plan">返回设计平面</button></div>'}</div><div class="canvas-bottom"><div><span class="status-dot"></span>${state.view==='plan'?'平面依据':state.view==='original'?'设计师原案':'一次性生成试验'}<span class="muted">${state.view==='axon'?'静态轴侧图 · 非三维模型':state.view==='perspective'?'C1 · 指定客厅朝庭院视角':'点击放大查看细节'}</span></div><div class="zoom-tools"><button data-action="zoom-out" aria-label="缩小">−</button><span id="zoom-value">100%</span><button data-action="zoom-in" aria-label="放大">+</button><button data-action="full-image" aria-label="打开完整图像">${ico('expand')}</button></div></div>${state.view!=='plan'&&!state.custom?`<div class="filmstrip">${[['original','原案基准'],['perspective','人视试生成'],['axon','首层轴侧']].map(([v,n])=>`<button data-view="${v}" class="${v===state.view?'active':''}"><img src="${v==='original'?asset('original-living.jpg'):photo(state.style,v)}" alt="${n}"><span>${n}</span></button>`).join('')}</div>`:''}<div class="canvas-note"><b>${state.view==='plan'?'图纸观察':state.view==='original'?'原案对照':'本轮观察'}</b><p>${state.view==='plan'?esc(r.desc):state.view==='original'?'此图来自客户原方案，仅用于事后对照，不计入本次 AI 生成成果。':state.custom?'等待本图纸的生成结果。':esc(observations[state.style+'-'+state.view][1])}</p><button class="text-btn" data-route="review">逐项核对 ${ico('arrow')}</button></div></section><aside class="settings-panel"><div class="panel-title"><h2>设计依据</h2><span class="pill">${state.custom?'新素材':'客户案例'}</span></div><div class="plan-preview">${planPanel(false)}<button class="text-btn" data-action="plan-source">${state.custom?'查看导入图纸':'查看平面原页 · P.40'} ${ico('expand')}</button></div><div class="panel-section"><div class="label-line"><h3>风格方向</h3><button class="text-btn" data-route="styles">解读</button></div><div class="style-picker">${styles.map(t=>`<button data-style="${t.id}" class="${state.style===t.id?'active':''}" aria-pressed="${state.style===t.id}"><img src="${asset(t.ref)}" alt=""><span>${t.name}<small>${t.id==='oriental'?'官山有溪 P.48':'Rimadesio P.49 / 55'}</small></span>${state.style===t.id?ico('check'):''}</button>`).join('')}</div><label class="form-label" for="brief">本轮设计要求</label><textarea id="brief" rows="3" maxlength="4000" placeholder="补充需保留或调整的细节…">${esc(state.brief||s.prompt)}</textarea><small class="field-hint">文字用于保存简报；修改不会重新生成当前图。</small></div><div class="panel-section"><h3>保留的空间约束</h3><div class="locks">${['墙体与房间关系','门窗与采光井','主要家具落点'].map(t=>`<span>${ico('lock')}${t}</span>`).join('')}</div><p class="field-hint">以上是生成要求，执行情况仍需核对。</p></div><div class="panel-section source-inputs"><button class="btn full" data-action="upload-plan">${ico('plus')} 导入新的平面图</button><button class="text-btn" data-action="upload-refs">添加参考图片（${uploads.refs?.length||0}/3）</button>${(uploads.refs||[]).length?`<div class="uploaded-refs">${uploads.refs.map((f,i)=>`<div><img src="${f.data}" alt="${esc(f.name)}"><button data-remove-ref="${i}" aria-label="移除${esc(f.name)}">×</button></div>`).join('')}</div>`:''}${state.custom?'<button class="text-btn" data-action="restore-case">返回官山有溪案例</button>':''}</div><div class="panel-cta"><button class="btn dark full" data-action="load-results">${state.custom?'准备生成简报':'查看本轮试生成'} ${ico('arrow')}</button><small>${state.custom?'尚未接入实时生成':'已生成 2 种风格 × 2 类视图'}</small></div></aside></div>${!state.custom?`<div class="room-index"><span>图纸空间索引</span>${rooms.map(r=>`<button data-room="${r.id}" class="${state.room===r.id?'active':''}">${r.n} ${r.name}</button>`).join('')}</div>`:''}</div>`;}
function stylePage(){const s=byStyle(state.style);return `<div class="page styles-page"><div class="page-title"><div><div class="project-kicker">风格研究 / 来自客户作品</div><h1>风格，是一套设计判断。</h1><p>把“想要的感觉”转译为可以选择、说明和核对的设计语言。</p></div><button class="btn dark" data-route="workspace">应用到工作台 ${ico('arrow')}</button></div><div class="style-tabs">${styles.map(t=>`<button class="${s.id===t.id?'active':''}" data-style="${t.id}"><span>${t.name}</span><small>${t.en}</small></button>`).join('')}</div><section class="style-editorial"><div class="style-cover"><img src="${asset(s.ref)}" alt="${s.name}风格参考原图"><span class="image-tag">客户参考 · 非生成图</span><button class="source-chip" data-page="${s.doc}:${s.page}">查看来源 · P.${s.page} ${ico('expand')}</button></div><div class="style-statement"><small>${s.en}</small><h2>${s.name}</h2><p class="serif">${s.subtitle}</p><p>${s.description}</p><div class="swatches large">${s.colors.map(c=>`<i style="background:${c}" title="${c}"></i>`).join('')}</div><span class="style-note">根据参考资料的设计解读 · 待设计师确认</span></div></section><div class="rule-grid">${s.rules.map(([k,v,d])=>`<article><small>${k}</small><h3>${v}</h3><p>${d}</p></article>`).join('')}</div><div class="master-note"><div><span class="small-square"></span><h3>“大师风格”需要具体到作品与细节。</h3><p>官山有溪第46页明确引用 Finn Juhl 的酋长椅。这能说明家具的设计来源，但不能据此将整套空间归为某一位大师的风格。Rimadesio 则属于品牌系统语言。后续如指定大师，应再选择具体作品、时期和可检验的设计特征。</p></div><button class="btn" data-page="guanshan:46">查看家具出处 ${ico('arrow')}</button></div><div class="section-head"><div><h2>从参考，到同一平面的表达</h2><p>当前选择：${s.name} · 结果存在空间偏差，进入审阅可查看详情。</p></div><button class="text-btn" data-route="review">核对本轮试验 ${ico('arrow')}</button></div><div class="style-output-grid"><button data-file="${s.id}-perspective.png" data-caption="${s.name} · 人视 AI 试生成"><img src="${photo(s.id)}" alt="${s.name}人视试生成"><span>客厅人视 ${ico('expand')}</span></button><button data-file="${s.id}-axon.png" data-caption="${s.name} · 首层轴侧 AI 试生成"><img src="${photo(s.id,'axon')}" alt="${s.name}首层轴侧试生成"><span>首层轴侧 ${ico('expand')}</span></button></div></div>`;}
function reviewKey(){return state.style+'-'+state.reviewView;}
function summary(){const vals=Object.values(state.reviews[reviewKey()]||{}),done=vals.filter(v=>v==='pass'||v==='fix').length,fix=vals.filter(v=>v==='fix').length;return `${done} / 6 项已评审${fix?' · '+fix+' 项需修改':''}`;}
function review(){const s=byStyle(state.style),v=state.reviewView,key=reviewKey(),rec=state.reviews[key]||{};return `<div class="page review-page"><div class="page-title"><div><div class="project-kicker">方案审阅 / 官山有溪首层</div><h1>好看之外，经得起核对。</h1><p>这四张图来自本次平面与风格输入的实际试生成。空间、材质和光照分别评估。</p></div><button class="btn dark" data-action="export-review">${ico('download')} 导出评审</button></div><div class="review-tools"><div class="segmented">${[['space','平面与结果'],['style','两种风格'],['original','原案与结果']].map(([id,n])=>`<button data-compare="${id}" class="${state.compare===id?'active':''}">${n}</button>`).join('')}</div><div class="review-selectors"><label>视图<select id="review-view"><option value="perspective" ${v==='perspective'?'selected':''}>客厅人视</option><option value="axon" ${v==='axon'?'selected':''}>首层轴侧</option></select></label><label>当前评审<select id="review-style">${styles.map(t=>`<option value="${t.id}" ${t.id===s.id?'selected':''}>${t.name}</option>`).join('')}</select></label></div></div><div class="comparison-grid">${state.compare==='style'?styles.map(t=>comparePane(photo(t.id,v),t.name,'AI 试生成 · 独立生成，机位未精确配准',t.id+'-'+v+'.png')).join(''):comparePane(state.compare==='space'?asset('guanshan-p40.jpg'):asset('original-living.jpg'),state.compare==='space'?'客户设计平面':'客户原案客厅',state.compare==='space'?'官山有溪 · P.40 · 原始设计依据':'官山有溪 · P.43 · 事后对照基准',state.compare==='space'?'guanshan-p40.jpg':'original-living.jpg')+comparePane(photo(s.id,v),s.name+' · '+(v==='axon'?'首层轴侧':'客厅人视'),'AI 试生成 · 待人工确认',s.id+'-'+v+'.png')}</div><div class="review-bottom"><section class="observations"><div class="panel-title"><h2>本轮观察</h2><span class="pill amber">存在偏差</span></div><p class="field-hint">视觉检查记录，非尺寸测量或设计师验收。</p>${observations[key].map((t,i)=>`<div class="observation"><span>${i===0?'↗':'!'}</span><p>${t}</p></div>`).join('')}<div class="ambiguity"><b>需要设计师确认的原案信息</b><p>第40页⑧的图例与房间内标注不一致；本轮按第48页“品茗区”理解。尺寸、标高及家具型号仍以完整设计文件为准。</p></div></section><section class="review-checks"><div class="panel-title"><h2>设计师评审</h2><span id="review-summary">${summary()}</span></div><p class="field-hint">记录归属：${s.name} / ${v==='axon'?'轴侧':'人视'}。手工选择仅代表本轮意见。</p><div class="check-grid">${reviewItems.map(([id,n])=>`<label><span>${n}</span><select data-review="${id}" aria-label="${n}评审"><option value="pending" ${!rec[id]||rec[id]==='pending'?'selected':''}>待确认</option><option value="pass" ${rec[id]==='pass'?'selected':''}>符合</option><option value="fix" ${rec[id]==='fix'?'selected':''}>需修改</option></select></label>`).join('')}</div><label class="form-label" for="review-note">给下一轮的修改意见</label><textarea id="review-note" maxlength="4000" rows="3" placeholder="例如：恢复左侧窗洞；简餐区回到四把座椅…">${esc(state.notes[key]||'')}</textarea><small class="field-hint">本机自动保存；导出评审可保留完整记录。</small></section></div></div>`;}
function comparePane(src,title,sub,file){return `<figure class="compare-pane"><figcaption><div><h3>${title}</h3><span>${sub}</span></div><button class="icon-btn" data-file="${file}" data-caption="${title}" aria-label="放大${title}">${ico('expand')}</button></figcaption><button class="compare-image ${file.includes('p40')?'paper':''}" data-file="${file}" data-caption="${title}" aria-label="查看${title}大图"><img src="${src}" alt="${title}"></button></figure>`;}
function archive(){const selected=docs.find(d=>d.id===state.selectedRef)||docs[0];return `<div class="page archive-page"><div class="page-title"><div><div class="project-kicker">素材档案 / 客户提供</div><h1>作品，是风格的证据。</h1><p>五份资料的精选页面与设计用途。保留出处，让每次判断都可回看。</p></div><button class="btn" data-action="sources">查看文件清单 ${ico('archive')}</button></div><div class="archive-layout"><div class="archive-list">${docs.map(d=>`<button data-doc="${d.id}" class="${d.id===selected.id?'active':''}"><small>${d.role} · ${d.pages} 页</small><h3>${d.name}</h3><p>${d.desc}</p></button>`).join('')}</div><section class="archive-content"><div class="section-head"><div><h2>${selected.name}</h2><p>精选 ${selected.sample.length} 页 · 点击查看完整原页</p></div><span class="pill">${selected.role}</span></div><div class="page-gallery">${selected.sample.map(n=>`<button data-page="${selected.id}:${n}"><img src="${asset(selected.id+'-p'+n+'.jpg')}" alt="${selected.name}第${n}页" loading="lazy"><span>P.${String(n).padStart(2,'0')} ${ico('expand')}</span></button>`).join('')}</div><p class="archive-footnote">页面中的品牌、作品与图像来自客户提供的资料。本演示保留来源，仅用于本次方案研究与讨论。</p></section></div></div>`;}
function modal(title,body,cls=''){const d=$('#modal');if(d.open)d.close();d.className=cls;d.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="关闭">${ico('close')}</button></div><div class="modal-body">${body}</div>`;d.showModal();}
function lightbox(file,caption){modal(esc(caption),`<img class="lightbox-image" src="${asset(file)}" alt="${esc(caption)}"><div class="lightbox-meta"><span>放大查看原始图像 · 可下载后核对细节</span><button class="btn" data-download="${file}">${ico('download')} 下载图像</button></div>`,'lightbox');}
function pageModal(id,n){const d=docs.find(d=>d.id===id);lightbox(`${id}-p${n}.jpg`,`${d.name} · 第${n}页 · 客户提供`);}
function sourceList(){modal('本次采用的设计资料',`<p>资料由客户提供。下列页码均为 PDF 文件页序；每份文件仅打包精选页面，不包含整本原 PDF。</p><div class="source-list">${docs.map(d=>`<div><b>${d.file}</b><p>${d.role} · 共 ${d.pages} 页</p><div>${d.sample.map(n=>`<button class="text-btn" data-page="${d.id}:${n}">P.${n}</button>`).join('')}</div></div>`).join('')}</div>`);}
function about(){modal('FORMA 序间 · 客户案例版',`<p>围绕官山有溪首层，演示“平面依据 → 风格定义 → 人视与轴侧试生成 → 逐项审阅”。</p><h3>这一版已经完成</h3><p>整理五份客户资料，提取首层平面和原案图，以同一张平面及两组风格参考，通过内置图像生成工具预先生成四张试验图。网页支持来源查看、风格切换、空间索引、人工评审、历史方案、本机素材导入与导出。</p><h3>生成输入与对照</h3><p>东方收藏：官山有溪 P.40 + P.48；意式秩序：官山有溪 P.40 + Rimadesio P.49 / P.55。客厅原案 P.43 用于事后对照，没有作为本次生成输入。</p><h3>当前验证结论</h3><p>两种材质语言可见差异，主要分区可辨识；吧台方向、座椅数量、部分窗洞与跨视图家具仍有偏差。未完成空间尺寸测量，不构成设计师验收。轴侧为静态图，非可编辑模型。</p><h3>演示范围</h3><p>网页未接入实时 AI 服务，修改文字、上传新图或参考图不会重新调用模型。新导入平面不套用本案例的生成结果。本机数据与浏览器关联，请导出备份。</p><button class="btn dark" data-action="close">返回设计空间 ${ico('arrow')}</button>`);}
function navigate(r){state.route=r;focused=false;document.body.classList.remove('menu-open');history.pushState(null,'','#'+r);persist();render();window.scrollTo(0,0);}
function download(data,mime,name){const u=URL.createObjectURL(new Blob([data],{type:mime})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
function downloadImage(file){const a=document.createElement('a');a.href=asset(file);a.download='FORMA_'+file;a.click();toast('图像下载已开始。');}
function report(){return {format:'forma-client-v2',project:title(),generatedFor:'官山有溪首层',customPlan:state.custom,style:byStyle(state.style).name,view:state.reviewView,designBrief:state.brief||byStyle(state.style).prompt,inputs:state.style==='oriental'?['官山有溪 P.40','官山有溪 P.48']:['官山有溪 P.40','Rimadesio P.49','Rimadesio P.55'],reviews:state.reviews,reviewNotes:state.notes,observations,sourceAmbiguity:'⑧图例儿童活动区，图内品茗区；暂按P.48品茗区理解',verification:'视觉检查及人工评审；未进行尺寸测量，未通过空间精度验收',runtimeGeneration:false,exportedAt:new Date().toISOString()};}
function briefMarkdown(){const r=report();return `# ${title()} — FORMA 设计简报\n\n风格：${r.style}\n\n## 设计要求\n${r.designBrief}\n\n## 生成依据\n${state.custom?'用户导入：'+(uploads.planName||'待导入')+'；尚无生成成果。':r.inputs.join('、')}\n\n## 空间约束\n墙体、门窗、房间关系、采光井及主要家具落点以平面为准。\n\n## 待确认\n${r.sourceAmbiguity}\n\n## 当前结果边界\n${r.verification}。网页未接入实时生成，现有四张图为一次性试生成；不能用于新导入平面。\n\n## 评审记录\n${JSON.stringify(state.reviews,null,2)}\n\n## 修改意见\n${JSON.stringify(state.notes,null,2)}\n\n## 资料来源\n${docs.map(d=>'- '+d.file+'（精选页：'+d.sample.join('、')+'）').join('\n')}\n`;}
function exportModal(){modal('导出方案资料',`<p>${esc(title())} · ${byStyle(state.style).name}</p><div class="export-options"><button class="btn" data-action="export-brief">${ico('download')}设计简报（Markdown）</button><button class="btn" data-action="export-review">${ico('download')}完整评审记录（JSON）</button><button class="btn" data-action="export-backup">${ico('download')}方案备份（含本机素材）</button>${!state.custom?`<button class="btn" data-download="${state.style}-perspective.png">${ico('download')}人视试生成（PNG）</button><button class="btn" data-download="${state.style}-axon.png">${ico('download')}轴侧试生成（PNG）</button>`:''}</div><p class="field-hint">图片为一次性试生成，仍有已记录偏差；不包含三维模型。</p>`);}
function saveVersion(){if(state.versions.length>=30){toast('已达到30个本机版本，请导出备份。');return;}state.versions.push({id:Date.now(),date:new Date().toISOString(),style:state.style,view:state.view,brief:state.brief,custom:state.custom,planName:uploads.planName||'',reviews:JSON.parse(JSON.stringify(state.reviews)),notes:{...state.notes}});persist();toast('已保存风格、要求与评审快照；上传素材保持项目当前版本。');}
function historyModal(){modal('历史方案',`<p>恢复风格、设计要求与评审快照。上传图纸和参考素材使用当前版本，不随历史记录回退。</p>${state.versions.length?state.versions.slice().reverse().map((v,i)=>`<div class="version-row"><div><b>V${state.versions.length-i} · ${byStyle(v.style).name}</b><small>${new Date(v.date).toLocaleString('zh-CN')} · ${v.custom?esc(v.planName):'官山有溪'}</small></div><button class="btn" data-restore="${v.id}">恢复</button></div>`).join(''):'<div class="empty-state"><h3>尚未保存方案</h3><p>在工作台点击“保存方案”建立第一份记录。</p></div>'}`);}
async function getDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('forma-client-assets',1);r.onupgradeneeded=()=>r.result.createObjectStore('assets');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function putAssets(next){if(!db)throw new Error('本机素材存储不可用，请使用常规浏览器窗口。');await new Promise((resolve,reject)=>{const t=db.transaction('assets','readwrite');t.objectStore('assets').put(next,'project');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||new Error('保存失败'));});uploads=next;}
async function readFile(f){if(!['image/png','image/jpeg','image/webp'].includes(f.type))throw new Error('请导入 PNG、JPG 或 WEBP 图像。');if(f.size>10*1024*1024)throw new Error('单张图片请控制在10 MB内。');const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(new Error('图片读取失败'));r.readAsDataURL(f);});await new Promise((res,rej)=>{const i=new Image();i.onload=res;i.onerror=()=>rej(new Error('无法识别此图片'));i.src=data;});return data;}
async function uploadPlan(f){if(!f)return;try{const data=await readFile(f);await putAssets({...uploads,plan:data,planName:f.name});state.custom=true;state.view='plan';state.brief='';zoom=1;navigate('workspace');toast('新图纸已导入；本案例试生成不会作为此图纸的结果。');}catch(e){toast(e.message);}$('#plan-file').value='';}
async function uploadRefs(fs){if(!fs.length)return;try{const refs=[...(uploads.refs||[])];if(refs.length+fs.length>3)throw new Error('最多保留3张参考图，请先移除已有参考。');for(const f of fs)refs.push({name:f.name,data:await readFile(f)});await putAssets({...uploads,refs});render();toast('参考图已保存在本机，用于后续生成简报。');}catch(e){toast(e.message);}$('#ref-file').value='';}
function bind(){if($('#brief'))$('#brief').oninput=e=>{state.brief=e.target.value;persist();};if($('#review-note'))$('#review-note').oninput=e=>{state.notes[reviewKey()]=e.target.value;persist();};if($('#review-view'))$('#review-view').onchange=e=>{state.reviewView=e.target.value;persist();render();};if($('#review-style'))$('#review-style').onchange=e=>{state.style=e.target.value;persist();render();};$$('[data-review]').forEach(el=>el.onchange=()=>{const k=reviewKey();state.reviews[k]={...(state.reviews[k]||{}),[el.dataset.review]:el.value};persist();$('#review-summary').textContent=summary();});const stage=$('#stage');if(stage){stage.ondragover=e=>{e.preventDefault();stage.classList.add('dragover');};stage.ondragleave=()=>stage.classList.remove('dragover');stage.ondrop=e=>{e.preventDefault();stage.classList.remove('dragover');uploadPlan(e.dataTransfer.files[0]);};}}
function setZoom(delta){zoom=Math.min(2,Math.max(.75,zoom+delta));const el=$('#stage>.result-img')||$('#stage>.plan-map');if(el)el.style.transform=`scale(${zoom})`;if($('#zoom-value'))$('#zoom-value').textContent=Math.round(zoom*100)+'%';}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;const d=el.dataset;if(d.route){navigate(d.route);return;}if(d.style){state.style=d.style;state.brief='';persist();render();return;}if(d.openStyle){state.style=d.openStyle;state.custom=false;state.brief='';state.view='perspective';navigate('workspace');return;}if(d.view){state.view=d.view;zoom=1;persist();render();return;}if(d.room){state.room=d.room;state.view='plan';zoom=1;persist();render();return;}if(d.compare){state.compare=d.compare;persist();render();return;}if(d.file){lightbox(d.file,d.caption||d.file);return;}if(d.page){const [id,n]=d.page.split(':');pageModal(id,n);return;}if(d.doc){state.selectedRef=d.doc;persist();render();return;}if(d.download){downloadImage(d.download);return;}if(d.removeRef!==undefined){try{await putAssets({...uploads,refs:uploads.refs.filter((_,i)=>i!==+d.removeRef)});render();toast('参考图已移除。');}catch(e){toast(e.message);}return;}if(d.restore){const v=state.versions.find(v=>v.id===+d.restore);if(v){Object.assign(state,{style:v.style,view:v.view,brief:v.brief,custom:v.custom&&!!uploads.plan,reviews:JSON.parse(JSON.stringify(v.reviews)),notes:{...v.notes}});$('#modal').close();persist();render();toast('方案已恢复，素材保持当前版本。');}return;}switch(d.action){case'menu':document.body.classList.toggle('menu-open');break;case'close':$('#modal').close();break;case'about':about();break;case'sources':sourceList();break;case'focus':focused=!focused;render();break;case'plan-source':if(state.custom)modal('导入平面',`<img class="lightbox-image" src="${uploads.plan}" alt="导入平面">`,'lightbox');else pageModal('guanshan',40);break;case'full-image':if(state.custom){if(state.view==='plan')modal('导入平面',`<img class="lightbox-image" src="${uploads.plan}" alt="导入平面">`,'lightbox');else toast('此图纸尚无生成结果。');}else lightbox(state.view==='plan'?'guanshan-p40.jpg':state.view==='original'?'original-living.jpg':state.style+'-'+state.view+'.png',state.view==='plan'?'首层设计平面':state.view==='original'?'客户原案':byStyle(state.style).name+' · AI试生成');break;case'zoom-in':setZoom(.1);break;case'zoom-out':setZoom(-.1);break;case'upload-plan':$('#plan-file').click();break;case'upload-refs':$('#ref-file').click();break;case'restore-case':state.custom=false;state.brief='';state.view='perspective';persist();render();break;case'load-results':if(state.custom){exportModal();}else{state.view='perspective';zoom=1;persist();render();toast('已载入本轮试生成。修改简报与参考图不会触发重新生成。');}break;case'save':saveVersion();break;case'history':historyModal();break;case'export':exportModal();break;case'export-review':download(JSON.stringify(report(),null,2),'application/json','FORMA_官山有溪_评审记录.json');toast('完整评审记录已导出。');break;case'export-brief':download(briefMarkdown(),'text/markdown;charset=utf-8','FORMA_设计简报.md');toast('设计简报已导出。');break;case'export-backup':download(JSON.stringify({format:'forma-client-v2-backup',state,uploads,report:report()},null,2),'application/json','FORMA_方案备份.json');toast('方案备份已导出。');break;}});
$('#plan-file').onchange=e=>uploadPlan(e.target.files[0]);$('#ref-file').onchange=e=>uploadRefs([...e.target.files]);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('menu-open');if(focused){focused=false;render();}}});
window.addEventListener('popstate',()=>{const r=location.hash.slice(1);if(['overview','workspace','styles','review','archive'].includes(r)){state.route=r;focused=false;render();}});
(async()=>{try{db=await getDB();uploads=await new Promise((resolve,reject)=>{const r=db.transaction('assets').objectStore('assets').get('project');r.onsuccess=()=>resolve(r.result||{});r.onerror=()=>reject(r.error);});}catch{console.warn('本机素材存储不可用');}if(state.custom&&!uploads.plan)state.custom=false;const r=location.hash.slice(1);if(['overview','workspace','styles','review','archive'].includes(r))state.route=r;render();})();
